    static member Create (?width: float, ?height: float, ?gravity: U2<string, BasicImageTransformationsGravityCoordinates>, ?zoom: float, ?fit: RequestInitCfPropertiesImageDrawFit, ?trim: U2<string, RequestInitCfPropertiesImageDrawTrim>, ?background: string, ?flip: RequestInitCfPropertiesImageDrawFlip, ?rotate: RequestInitCfPropertiesImageDrawRotate, ?sharpen: float, ?blur: float, ?contrast: float, ?brightness: float, ?gamma: float, ?saturation: float, ?dpr: float, ?border: U2<RequestInitCfPropertiesImageDrawBorder, RequestInitCfPropertiesImageDrawBorder2>, ?segment: string, ?upscale: RequestInitCfPropertiesImageDrawUpscale) : BasicImageTransformations = jsNative

